package dev.rapbattle.battle;

// Generated by tools/gen_beats.py from the fitted tracks. Do not edit by hand.

import dev.rapbattle.Lang;

import java.util.List;
import java.util.Map;

/** The real beats: each loops exactly on the battle grid (one beat = beatMs, the file is a whole number of bars). */
public final class BeatTracks {
	private BeatTracks() {}

	private static final Map<String, String> NAME_EN = Map.of(
		"breaks", "breakbeat",
		"knock", "hard drums",
		"stomp", "stomp",
		"trapdrums", "trap drums",
		"battle", "battle",
		"streets", "streets",
		"trap", "trap",
		"drill", "drill",
		"boss", "boss");

	public record Track(String id, String name, int beatMs, int bars) {
		public double bpm() { return 60000.0 / beatMs; }

		public String name(String lang) { return Lang.isRu(lang) ? name : NAME_EN.getOrDefault(id, name); }
	}

	public static final List<Track> ALL = List.of(
		new Track("breaks", "брейкбит", 714, 20),
		new Track("knock", "жёсткие ударные", 652, 20),
		new Track("stomp", "топот", 612, 20),
		new Track("trapdrums", "трэп-ударные", 578, 24),
		new Track("battle", "баттл", 682, 20),
		new Track("streets", "улица", 625, 20),
		new Track("trap", "трэп", 601, 24),
		new Track("drill", "дрилл", 566, 24),
		new Track("boss", "босс", 525, 28));

	public static Track byId(String id) {
		for (Track t : ALL) if (t.id().equals(id)) return t;
		return null;
	}
}
